mapper.select:
SELECT total_annual_leave
FROM leave_balance
WHERE employee_id = #{employeeId} AND base_year = #{baseYear}

SELECT grant_history_id as grantHistoryId, employee_id as employeeId, base_year as baseYear, grant_date as grantDate, grant_days as grantDays, grant_type as grantType, reason, created_at as createdAt FROM leave_grant_history WHERE employee_id = #{employeeId}
AND base_year = #{baseYear}
ORDER BY grant_date DESC, grant_history_id DESC

SELECT IFNULL(SUM(used_days), 0)
FROM leave_request
WHERE employee_id = #{employeeId}
  AND leave_status = #{status}
  AND YEAR(start_date) = #{year}

mapper.insert:
INSERT INTO leave_request (
    approval_id, employee_id, start_date, end_date, leave_type, leave_status, used_days, reason
) VALUES (
            #{approvalId}, #{employeeId}, #{startDate}, #{endDate}, #{leaveType}, #{leaveStatus}, #{usedDays}, #{reason}
        )

mapper.select:
SELECT COUNT(*)
FROM leave_request
WHERE employee_id = #{employeeId}

mapper.update:
UPDATE leave_request
SET leave_status = #{leaveStatus},
    reject_reason = #{rejectReason}
WHERE leave_request_id = #{leaveRequestId}
    AND leave_status = 'PENDING'

mapper.select:
SELECT lr.leave_request_id as leaveRequestId, lr.approval_id as approvalId, lr.employee_id as employeeId, lr.start_date as startDate, lr.end_date as endDate, lr.leave_type as leaveType, lr.leave_status as leaveStatus, lr.used_days as usedDays, lr.reason as reason, lr.reject_reason as rejectReason FROM leave_request lr
lr.leave_status = #{leaveStatus}
ORDER BY lr.start_date DESC, lr.leave_request_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM leave_request
WHERE employee_id = #{employeeId}
  AND leave_status IN ('PENDING', 'APPROVED')
  AND start_date <= #{endDate}
  AND end_date >= #{startDate}
